plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.kotlin.compose)
}

// ---------------------------------------------------------------- Rust
//
// beam-core-ffi is built for each ABI with cargo-ndk, and its Kotlin
// bindings are generated by UniFFI from the built library, before every
// Android build. Needs `cargo` and `cargo-ndk` on PATH (see android/README.md).

val repoRoot: File = rootProject.projectDir.parentFile
val rustJniLibs = layout.buildDirectory.dir("rust/jniLibs")
val uniffiKotlin = layout.buildDirectory.dir("generated/uniffi/kotlin")
val abis = providers.gradleProperty("beam.abis").get().split(",").map { it.trim() }.filter { it.isNotEmpty() }

android {
    namespace = "dev.beam.android"
    compileSdk = 37
    ndkVersion = "30.0.16248370"

    defaultConfig {
        applicationId = "dev.beam.android"
        minSdk = 29
        targetSdk = 37
        versionCode = 1
        versionName = "0.1.0"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        // Only the ABIs libbeam_core_ffi.so is built for (ML Kit ships more).
        ndk { abiFilters += abis }
    }

    signingConfigs {
        // One debug key for every machine and CI run, so a new build
        // installs over the last one. A different key forces an uninstall,
        // which wipes the device's identity and its trusted devices.
        // Not secret: it signs debug builds only.
        getByName("debug") {
            storeFile = file("debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildFeatures {
        compose = true
    }

    sourceSets {
        getByName("main") {
            // Filled by the Rust tasks below.
            jniLibs.directories.add(rustJniLibs.get().asFile.path)
            kotlin.directories.add(uniffiKotlin.get().asFile.path)
        }
    }

    testOptions {
        // JVM unit tests never load the native library.
        unitTests.isReturnDefaultValues = true
    }
}

val cargoNdkBuild = tasks.register<Exec>("cargoNdkBuild") {
    description = "Builds libbeam_core_ffi.so for each Android ABI."
    workingDir = repoRoot
    val outDir = rustJniLibs.get().asFile
    val ndkDir = androidComponents.sdkComponents.ndkDirectory
    inputs.files(fileTree(repoRoot.resolve("core/src")), fileTree(repoRoot.resolve("core-ffi/src")))
    inputs.files(repoRoot.resolve("core/Cargo.toml"), repoRoot.resolve("core-ffi/Cargo.toml"), repoRoot.resolve("Cargo.lock"))
    inputs.property("abis", abis)
    outputs.dir(outDir)
    doFirst { environment("ANDROID_NDK_HOME", ndkDir.get().asFile.path) }
    commandLine(
        buildList {
            addAll(listOf("cargo", "ndk"))
            abis.forEach { addAll(listOf("-t", it)) }
            addAll(listOf("-o", outDir.path, "build", "-p", "beam-core-ffi", "--release"))
        },
    )
}

val uniffiBindings = tasks.register<Exec>("uniffiBindings") {
    description = "Generates the Kotlin bindings for beam-core-ffi."
    dependsOn(cargoNdkBuild)
    workingDir = repoRoot
    val library = rustJniLibs.get().asFile.resolve("${abis.first()}/libbeam_core_ffi.so")
    val outDir = uniffiKotlin.get().asFile
    inputs.file(library)
    inputs.file(repoRoot.resolve("core-ffi/uniffi.toml"))
    outputs.dir(outDir)
    commandLine(
        "cargo", "run", "-q", "-p", "beam-core-ffi", "--features", "bindgen", "--bin", "uniffi-bindgen", "--",
        "generate", "--library", library.path, "--language", "kotlin", "--no-format", "--out-dir", outDir.path,
    )
}

tasks.named("preBuild") { dependsOn(uniffiBindings) }

dependencies {
    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.activity.compose)
    implementation(libs.androidx.lifecycle.viewmodel.compose)
    implementation(libs.androidx.lifecycle.runtime.compose)
    implementation(libs.androidx.lifecycle.service)
    implementation(platform(libs.compose.bom))
    implementation(libs.compose.ui)
    implementation(libs.compose.ui.tooling.preview)
    implementation(libs.compose.material3)
    implementation(libs.compose.material.icons)
    implementation(libs.kotlinx.coroutines.android)
    implementation(libs.camera.camera2)
    implementation(libs.camera.lifecycle)
    implementation(libs.camera.view)
    implementation(libs.mlkit.barcode)
    // UniFFI's generated Kotlin calls into the Rust library through JNA.
    implementation("${libs.jna.get()}@aar")
    debugImplementation(libs.compose.ui.tooling)

    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)

    androidTestImplementation(libs.androidx.test.ext.junit)
    androidTestImplementation(libs.androidx.test.espresso)
    androidTestImplementation(platform(libs.compose.bom))
    androidTestImplementation(libs.compose.ui.test.junit4)
    debugImplementation(libs.compose.ui.test.manifest)
}
